'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies } = require('./src/semver');

// caret on zero majors
assert.equal(satisfies('0.2.9', '^0.2.0'), true);
assert.equal(satisfies('0.3.0', '^0.2.0'), false);
assert.equal(satisfies('0.0.3', '^0.0.3'), true);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);

// backtracking must undo constraints of a rejected choice
assert.deepEqual(resolve({
  a: { '2.0.0': { c: '^2.0.0', b: '^1.0.0' }, '1.0.0': { b: '^1.0.0' } },
  b: { '1.0.0': { c: '^1.0.0' } },
  c: { '1.0.0': {}, '2.0.0': {} },
}, { a: '*' }), { a: '1.0.0', b: '1.0.0', c: '1.0.0' });

// cycles
assert.deepEqual(resolve({
  x: { '1.0.0': { y: '1.0.0' } }, y: { '1.0.0': { x: '1.0.0' } },
}, { x: '*' }), { x: '1.0.0', y: '1.0.0' });

// long chain
const n = 20000;
const reg = {};
for (let i = 0; i < n; i++) reg['p' + i] = { '1.0.0': i + 1 < n ? { ['p' + (i + 1)]: '^1.0.0' } : {} };
assert.equal(Object.keys(resolve(reg, { p0: '*' })).length, n);

// deep conflict with wide choices: must prune, not enumerate 10^30
const wide = { z: { '1.0.0': {} } };
const root = {};
for (let i = 0; i < 30; i++) {
  wide['w' + i] = {};
  for (let v = 0; v < 10; v++) wide['w' + i][`1.${v}.0`] = {};
  root['w' + i] = '*';
}
root.z = '^2.0.0';
assert.equal(resolve(wide, root), null);

// missing package unsatisfiable; empty root
assert.equal(resolve({}, { nope: '*' }), null);
assert.deepEqual(resolve({ a: { 'bad': {} } }, {}) === undefined, false);
console.log('ok');

